public interface IInvoiceService
{
    Task<InvoiceResult> GenerateAsync(InvoiceRequest request);
}

public class InvoiceService : IInvoiceService
{
    private readonly IPdfGenerator _pdfGenerator;
    private readonly IInvoiceRepository _repository;

    public InvoiceService(IPdfGenerator pdfGenerator, IInvoiceRepository repository)
    {
        _pdfGenerator = pdfGenerator;
        _repository = repository;
    }

    public async Task<InvoiceResult> GenerateAsync(InvoiceRequest request)
    {
        var invoice = await _repository.GetByIdAsync(request.InvoiceId);
        var pdfBytes = await _pdfGenerator.GeneratePdfAsync(invoice);
        return new InvoiceResult { PdfBytes = pdfBytes, FileName = $"Invoice-{invoice.Number}.pdf" };
    }
}

public class InvoiceProcessingWorker : BackgroundService
{
    private readonly Channel<InvoiceRequest> _channel;
    private readonly IInvoiceService _invoiceService;
    private readonly ILogger<InvoiceProcessingWorker> _logger;
    private const int MaxConcurrency = 8;

    public InvoiceProcessingWorker(Channel<InvoiceRequest> channel, IInvoiceService invoiceService, ILogger<InvoiceProcessingWorker> logger)
    {
        _channel = channel;
        _invoiceService = invoiceService;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var semaphore = new SemaphoreSlim(MaxConcurrency);
        await foreach (var request in _channel.Reader.ReadAllAsync(stoppingToken))
        {
            await semaphore.WaitAsync(stoppingToken);
            _ = Task.Run(async () =>
            {
                try
                {
                    await _invoiceService.GenerateAsync(request);
                }
                finally
                {
                    semaphore.Release();
                }
            }, stoppingToken);
        }
    }
}
